    expect(await ui.pasteClaims(pg_vic, "Ada,1.00,,")).toBeNull();
    expect(await ui.bulkOpen(pg_vic, [c_ada_1])).toEqual({ opened: 0, refused: 1 });
    expect(await ui.bulkSettle(pg_vic, [c_ada_0])).toEqual({ settled: 0, refused: 1 });
